-- Show all colums of a given table with comments ------------------------------
select  
--        tcol.column_name,
--        tcol.data_type,
        rpad(tcol.column_name,40,' ') || ' ' || tcol.data_type ||  
        case when tcol.data_type in ('VARCHAR2','NUMBER') then '(' else null end ||
        case tcol.data_type 
            when 'VARCHAR2' then to_char(tcol.data_length) 
            when 'NUMBER'   then to_char(tcol.data_precision) || ',' || to_char(tcol.data_scale) 
            else null
        end ||
        case when tcol.data_type in ('VARCHAR2','NUMBER') then ')' else null end || ',' as field_row
from    sys.all_tab_columns     tcol
where   tcol.owner = 'BSI'
    and tcol.table_name like 'BSI%'
order   by  tcol.column_name
;

select  *
from    bsi.sbu_select_generator
where   1=1
;

drop table sbu_select_generator
;

