-- Generate select clause for a given table with all columns within this table and a translation for UIDs ------------------------------
with 
    w_settings_input as 
    (
        select  'sbu_select_generator'          as  table_name,
                ''          as  table_alias,
                100         as  lob_length
        from    dual
    ),
    w_settings as
    (
        select  s.table_name,
                case when s.table_alias is null then
                    case upper(s.table_name) when 'BSI_ACTION' then 'acti' when 'BSI_ACTION_REACTION' then 'acra' when 'BSI_ACTION_RECIPIENT' then 'acre' when 'BSI_ACTION_RECIPIENT_HISTORY' then 'acrh' when 'BSI_ACTION_REVIEW_STATUS' then 'acrs' when 'BSI_ACTION_RUN' then 'acru' when 'BSI_ACTION_SEARCH' then 'acse' when 'BSI_ADDRESS' then 'addr' when 'BSI_ADDRESS_USAGE' then 'adus' when 'BSI_BENEFIT' then 'bene' when 'BSI_BENEFIT_CHANGE' then 'benc' when 'BSI_BOOKMARK' then 'boma' when 'BSI_BUSINESS' then 'busi' when 'BSI_BUSINESS_CHANGE' then 'busc' when 'BSI_BUSINESS_ROLE' then 'buro' when 'BSI_BUSINESS_STATUS' then 'bust' when 'BSI_CAMPAIGN' then 'camp' when 'BSI_CAMPAIGN_CHANGE' then 'camc' when 'BSI_CASE' then 'cass' when 'BSI_CASE_CHANGE' then 'casc' when 'BSI_CASE_INPUT' then 'caip' when 'BSI_CASE_ITEM' then 'casi' when 'BSI_CASE_LIST' then 'cali' when 'BSI_CASE_LOG' then 'calo' when 'BSI_CASE_MEMO' then 'came' when 'BSI_CASE_MEMO_CHANGE' then 'camc' when 'BSI_CASE_STEP' then 'cast' when 'BSI_CASE_STEP_HISTORY' then 'cash' when 'BSI_CASE_STEP_OUTPUT' then 'caso' when 'BSI_CATEGORY' then 'cate' when 'BSI_CATEGORY_ITEM' then 'cati' when 'BSI_CHANGE_PUBLISH' then 'chpu' when 'BSI_CITY' then 'city' when 'BSI_CODE_TYPE' then 'coty' when 'BSI_COMMUNICATION' then 'comm' when 'BSI_COMMUNICATION_CHANGE' then 'comc' when 'BSI_COMMUNICATION_PARTICIPANT' then 'comp' when 'BSI_COMMUNICATION_REACTION' then 'comr' when 'BSI_COMMUNICATION_STATUS' then 'coms' when 'BSI_CTI_CALL' then 'ctic' when 'BSI_CUSTOMER' then 'cust' when 'BSI_CUSTOMER_ADVISOR' then 'cusa' when 'BSI_CUSTOMER_CHANGE' then 'cusc' when 'BSI_CUSTOMER_CUSTOMER' then 'cucu' when 'BSI_CUSTOMER_CUSTOMER_ROLE' then 'cucr' when 'BSI_CUSTOMER_IMPORT' then 'cusi' when 'BSI_DEEP_LINK' then 'deli' when 'BSI_DEFAULT_ADDRESS_CALC' then 'dadc' when 'BSI_DISTRIBUTOR' then 'dist' when 'BSI_DISTRIBUTOR_CUSTOMER' then 'dicu' when 'BSI_DOCUMENT' then 'docu' when 'BSI_DOCUMENT_CONTENT' then 'docc' when 'BSI_DWH_INDEX' then 'dwhi' when 'BSI_EMPLOYEE' then 'empl' when 'BSI_ETL_LOG' then 'etll' when 'BSI_FOLDER' then 'fold' when 'BSI_FOLDER_CONTENT' then 'folc' when 'BSI_GLOBAL_COUNTER' then 'gloc' when 'BSI_GLOBAL_KEY_STATE' then 'glks' when 'BSI_GLOBAL_TEXT' then 'gltx' when 'BSI_GROUPWARE_ACCOUNT' then 'gwac' when 'BSI_IMPORT_CUSTOMER' then 'imcu' when 'BSI_IMPORT_DATA' then 'imda' when 'BSI_IMPORT_DATA_DUPLICATE' then 'imdd' when 'BSI_IMPORT_DATA_EXISTING' then 'imde' when 'BSI_IMPORT_META' then 'imme' when 'BSI_ITEM_SUMMARY' then 'itsu' when 'BSI_ITEM_SUMMARY_FILTER' then 'itsf' when 'BSI_ITEM_TEMPLATE_LANGUAGE' then 'ittl' when 'BSI_ITEM_TEXT' then 'ittx' when 'BSI_JOB' then 'jobb' when 'BSI_JOB_CHANGE' then 'jobc' when 'BSI_JOB_LOG' then 'jobl' when 'BSI_JOB_RUN' then 'jobr' when 'BSI_JOB_RUN_FILE' then 'jobf' when 'BSI_KNOWLEDGE' then 'know' when 'BSI_KNOWLEDGE_CHANGE' then 'knoc' when 'BSI_KNOWLEDGE_LANGUAGE' then 'knol' when 'BSI_KNOWLEDGE_PROCESS' then 'knop' when 'BSI_NEWSFEED' then 'newf' when 'BSI_NEWSFEED_RESPONSIBLE' then 'nefr' when 'BSI_OPERATION_EXECUTION' then 'opex' when 'BSI_OPT_IN' then 'opti' when 'BSI_ORGANIZATION_UNIT_FLAT' then 'oruf' when 'BSI_PARAMETER' then 'para' when 'BSI_PARAMETER_CHANGE' then 'parc' when 'BSI_PARAMETER_LIST' then 'parl' when 'BSI_PARAMETER_TO_CLUSTER_NODE' then 'parn' when 'BSI_PARAMETER_TO_ROLE' then 'parr' when 'BSI_RULE_EXECUTION' then 'rexe' when 'BSI_RULE_EXECUTION_COMPLETED' then 'rexc' when 'BSI_RULE_LOG' then 'rlog' when 'BSI_RULE_RUN' then 'rrun' when 'BSI_SOURCE_MAPPING' then 'soma' when 'BSI_TASK' then 'tasi' when 'BSI_TASK_CHANGE' then 'tasc' when 'BSI_TASK_PARTICIPANT' then 'tasp' when 'BSI_TRANSACTION' then 'tran' when 'BSI_USER' then 'usrt' when 'BSI_USER_ACL' then 'usra' when 'BSI_USER_OU_ACL' then 'usoa' when 'BSI_USER_PERMISSION_SNAPSHOT' then 'usrp' when 'BSI_USER_ROLE' then 'usro' when 'BSI_USER_SEARCH_PREFERENCE' then 'ussp' when 'BSI_USER_SUBSTITUTE' then 'ussu' 
                        else 
                            lower(
                                substr(s.table_name,instr(s.table_name,'_',1,1)+1, case regexp_count(s.table_name,'_') when 1 then 4 when 2 then 2 when 3 then 2 else 1 end) || 
                                substr(s.table_name,instr(s.table_name,'_',1,2)+1, case regexp_count(s.table_name,'_') when 1 then 0 when 2 then 2 when 3 then 1 else 1 end) ||
                                substr(s.table_name,instr(s.table_name,'_',1,3)+1, case regexp_count(s.table_name,'_') when 1 then 0 when 2 then 0 when 3 then 1 else 1 end) ||
                                substr(s.table_name,instr(s.table_name,'_',1,4)+1, case regexp_count(s.table_name,'_') when 1 then 0 when 2 then 0 when 3 then 0 else 1 end)  
                            ) 
                    end 
                else s.table_alias end as table_alias,
                s.lob_length
        from    w_settings_input    s
    ),
    w_columns as 
    (
        select  tcol.column_id,
                first_value(tcol.column_id) ignore nulls over (partition by tcol.table_name order by tcol.column_id rows between unbounded preceding and unbounded following) as first_column_id,
                last_value(tcol.column_id)  ignore nulls over (partition by tcol.table_name order by tcol.column_id rows between unbounded preceding and unbounded following) as last_column_id,
                lower(tcol.column_name) as column_name,
                lower(coalesce(sett.table_alias,tcol.table_name) || '.' || tcol.column_name) as column_name_full,
                tcol.data_type,
                tcol.owner,
                lower(tcol.table_name) as table_name,
                lower(coalesce(sett.table_alias,sett.table_name)) as table_alias,
                tcol.data_precision,
                case when tcol.data_scale > 0 then 2 else tcol.data_scale end as data_scale,
                '''' || regexp_replace(substr(replace(lpad('9',tcol.data_precision+3-mod(tcol.data_precision,3),'9'),'999','G999'),-tcol.data_precision-trunc(tcol.data_precision/3)),'^G','') || case when tcol.data_scale > 0 then rpad('D', tcol.data_scale, '9') else '' end || '''' as number_format,
                sett.lob_length,
                last_value(length(coalesce(sett.table_alias,tcol.table_name) || '.' || tcol.column_name)) ignore nulls over (partition by tcol.table_name order by length(tcol.column_name) rows between unbounded preceding and unbounded following) as max_name_size,
                length(coalesce(sett.table_alias,tcol.table_name) || '.' || tcol.column_name) as name_size                
        from    w_settings                          sett
                inner join  sys.all_tab_columns     tcol    on  tcol.table_name = upper(sett.table_name)
    )
select  case when first_column_id = column_id then 'select  ' else '        ' end || 
        case  
            when data_type = 'CLOB' then 'to_char(substr('
            when data_type = 'NUMBER' and data_scale > 0 then 'balutl_number(' 
            else '' 
        end ||  
        column_name_full || 
        case  
            when data_type = 'CLOB' then ',1,' || trim(to_char(lob_length,'9999')) || '))' || lpad('as  ', max_name_size-name_size+69,' ') || column_name
            when data_type = 'NUMBER' and data_scale > 0 then ', ' || data_scale || ', 12)' || lpad('as  ', max_name_size-name_size+70) || column_name 
            else '' 
        end ||  
        case when column_name like '%\_uid' escape '\' then 
                rpad(',', max_name_size-name_size+16, ' ') || 'balutl_uctext(' || column_name_full || ',2)' || rpad(' ', max_name_size-name_size+20, ' ') || 'as  ' || replace(column_name,'_uid', '_name') 
            when column_name like '%item_type_id' then 
                rpad(',', max_name_size-name_size+16, ' ') || 'balutl_itemtype(' || column_name || ',2)' || lpad('as  ', max_name_size-name_size+27) || replace(column_name,'_id', '_name')
            when column_name like '%item_key0_nr' then
                rpad(',', max_name_size-name_size+16, ' ') || 'balutl_itemname(' || replace(column_name,'key0_nr','type_id') || ',' || column_name || ')' || lpad('as  ', max_name_size-name_size-length(replace(column_name,'key0_nr','type_id'))+28) || replace(column_name,'_nr', '_name')
            when column_name like '%user_nr'        then rpad(',', max_name_size-name_size+16, ' ') || 'balutl_itemname(103380,' || column_name || ',1)' || lpad('as  ', max_name_size-name_size+20) || replace(column_name,'user_nr','user_name')
            when column_name like '%customer_nr'    then rpad(',', max_name_size-name_size+16, ' ') || 'balutl_itemname(318596,' || column_name || ',1)' || lpad('as  ', max_name_size-name_size+20) || replace(column_name,'customer_nr','customer_name')
            when column_name like '%contract_nr'    then rpad(',', max_name_size-name_size+16, ' ') || 'balutl_itemname(112102,' || column_name || ',1)' || lpad('as  ', max_name_size-name_size+20) || replace(column_name,'contract_nr','contract_name')
            when column_name like '%campaign_nr'    then rpad(',', max_name_size-name_size+16, ' ') || 'balutl_itemname(359571,' || column_name || ',1)' || lpad('as  ', max_name_size-name_size+20) || replace(column_name,'campaign_nr','campaign_name')
            when column_name like '%business_nr'    then rpad(',', max_name_size-name_size+16, ' ') || 'balutl_itemname(318595,' || column_name || ',1)' || lpad('as  ', max_name_size-name_size+20) || replace(column_name,'business_nr','business_name')
            when column_name like '%case_nr'        then rpad(',', max_name_size-name_size+16, ' ') || 'balutl_itemname(108596,' || column_name || ',1)' || lpad('as  ', max_name_size-name_size+20) || replace(column_name,'case_nr','case_name')
            else '' end || 
        case when last_column_id = column_id then chr(10) || 'from    ' || table_name || ' ' || table_alias || chr(10) || 'where   1=1' || chr(10) || ';' else ',' end 
            as sel_clause
from    w_columns
order   by  column_id;
